            #[repr(transparent)]
            #[derive(Clone, Copy)]
            pub struct $rf<'a>(CBorrowedPtr<'a, $name>);

            #[doc = concat!(
                "Exclusive borrow of an [`", stringify!($name), "`]. ",
                "Reaches the value through [`as_ref`](Self::as_ref)."
