            const _: () = {
                assert!(size_of::<$name>() == size_of::<sys::$c_name>());
                assert!(align_of::<$name>() == align_of::<sys::$c_name>());
                assert!(size_of::<$atomic>() == size_of::<$int>());
                assert!(align_of::<sys::$c_name>() >= align_of::<$atomic>());
            };

