                    // `$name` is transparent over `UnsafeCell<sys::$c_name>`, so the cast
                    // addresses its `sys::$c_name`; the projection forms no reference and reads
                    // nothing.
                    let val = unsafe { &raw mut (*cell.cast::<sys::$c_name>()).val };
