        /// ```
        ///
        /// Wraps `st::git_atomic32`
        #[doc(alias = "git_atomic32")]
        Atomic32,
        Atomic32Ref,
        Atomic32Mut,
        git_atomic32,
        AtomicI32,
        i32,
        val:
